def solve_limit_1_exact(max_q):
    possible_xyz = list(itertools.product(range(2), repeat=3))
    possible_abc = list(itertools.product(range(2), repeat=3))

    for num_q in range(1, max_q + 1):
        # Use combinations_with_replacement because Maria can ask the same question (though not helpful)
        # and we want to see if any set of num_q questions works.
        for qs in itertools.combinations_with_replacement(possible_abc, num_q):
            responses = {}
            for xyz in possible_xyz:
                r = get_responses(xyz, qs)
                responses[r] = responses.get(r, 0) + 1
            if all(count == 1 for count in responses.values()):
                return num_q
    return "more than " + str(max_q)

